using System;
using System.Collections.Generic;
using System.Globalization;
using System.Text;

namespace Bit.BlazorUI.Build;

/// <summary>
/// Reads the manifests build-assets.mjs writes: objects, arrays, strings, numbers, booleans and null, into
/// <see cref="Dictionary{TKey, TValue}"/>, <see cref="List{T}"/>, <see cref="string"/>, <see cref="double"/>,
/// <see cref="bool"/> and <see langword="null"/>.
/// </summary>
/// <remarks>
/// By hand rather than through System.Text.Json, which is not a dependency MSBuild guarantees a task in every host:
/// the manifests are small, generated by this repository's own script, and need nothing more than this.
/// </remarks>
public static class Json
{
    public static object? Parse(string text)
    {
        var position = 0;
        var value = ReadValue(text, ref position);
        SkipWhitespace(text, ref position);
        if (position != text.Length) throw Error(text, position, "unexpected content after the value");
        return value;
    }

    public static Dictionary<string, object?> AsObject(object? value, string what)
        => value as Dictionary<string, object?> ?? throw new FormatException($"{what}: expected an object.");

    public static List<object?> AsArray(object? value, string what)
        => value as List<object?> ?? throw new FormatException($"{what}: expected an array.");

    public static string GetString(Dictionary<string, object?> obj, string key, string what)
        => obj.TryGetValue(key, out var value) && value is string s ? s : throw new FormatException($"{what}: expected a string '{key}'.");

    public static string? GetOptionalString(Dictionary<string, object?> obj, string key)
        => obj.TryGetValue(key, out var value) ? value as string : null;

    public static bool GetBool(Dictionary<string, object?> obj, string key)
        => obj.TryGetValue(key, out var value) && value is true;

    public static double GetNumber(Dictionary<string, object?> obj, string key, string what)
        => obj.TryGetValue(key, out var value) && value is double d ? d : throw new FormatException($"{what}: expected a number '{key}'.");

    public static List<string> GetStrings(Dictionary<string, object?> obj, string key)
    {
        var result = new List<string>();
        if (obj.TryGetValue(key, out var value) && value is List<object?> items)
        {
            foreach (var item in items)
            {
                if (item is string s) result.Add(s);
            }
        }
        return result;
    }

    private static object? ReadValue(string text, ref int position)
    {
        SkipWhitespace(text, ref position);
        if (position >= text.Length) throw Error(text, position, "unexpected end");

        var c = text[position];
        switch (c)
        {
            case '{': return ReadObject(text, ref position);
            case '[': return ReadArray(text, ref position);
            case '"': return ReadString(text, ref position);
            case 't': Expect(text, ref position, "true"); return true;
            case 'f': Expect(text, ref position, "false"); return false;
            case 'n': Expect(text, ref position, "null"); return null;
            default:
                if (c == '-' || (c >= '0' && c <= '9')) return ReadNumber(text, ref position);
                throw Error(text, position, $"unexpected '{c}'");
        }
    }

    private static Dictionary<string, object?> ReadObject(string text, ref int position)
    {
        var result = new Dictionary<string, object?>(StringComparer.Ordinal);
        position++;
        SkipWhitespace(text, ref position);
        if (Peek(text, position) == '}') { position++; return result; }

        while (true)
        {
            SkipWhitespace(text, ref position);
            if (Peek(text, position) != '"') throw Error(text, position, "expected a property name");
            var key = ReadString(text, ref position);
            SkipWhitespace(text, ref position);
            if (Peek(text, position) != ':') throw Error(text, position, "expected ':'");
            position++;
            result[key] = ReadValue(text, ref position);
            SkipWhitespace(text, ref position);
            var next = Peek(text, position);
            position++;
            if (next == '}') return result;
            if (next != ',') throw Error(text, position - 1, "expected ',' or '}'");
        }
    }

    private static List<object?> ReadArray(string text, ref int position)
    {
        var result = new List<object?>();
        position++;
        SkipWhitespace(text, ref position);
        if (Peek(text, position) == ']') { position++; return result; }

        while (true)
        {
            result.Add(ReadValue(text, ref position));
            SkipWhitespace(text, ref position);
            var next = Peek(text, position);
            position++;
            if (next == ']') return result;
            if (next != ',') throw Error(text, position - 1, "expected ',' or ']'");
        }
    }

    private static string ReadString(string text, ref int position)
    {
        position++;
        var builder = new StringBuilder();
        while (true)
        {
            if (position >= text.Length) throw Error(text, position, "unterminated string");
            var c = text[position++];
            if (c == '"') return builder.ToString();
            if (c != '\\') { builder.Append(c); continue; }

            if (position >= text.Length) throw Error(text, position, "unterminated escape");
            var e = text[position++];
            switch (e)
            {
                case '"': builder.Append('"'); break;
                case '\\': builder.Append('\\'); break;
                case '/': builder.Append('/'); break;
                case 'b': builder.Append('\b'); break;
                case 'f': builder.Append('\f'); break;
                case 'n': builder.Append('\n'); break;
                case 'r': builder.Append('\r'); break;
                case 't': builder.Append('\t'); break;
                case 'u':
                    if (position + 4 > text.Length) throw Error(text, position, "truncated \\u escape");
                    builder.Append((char)int.Parse(text.Substring(position, 4), NumberStyles.HexNumber, CultureInfo.InvariantCulture));
                    position += 4;
                    break;
                default: throw Error(text, position - 1, $"unknown escape '\\{e}'");
            }
        }
    }

    private static double ReadNumber(string text, ref int position)
    {
        var start = position;
        while (position < text.Length && "+-0123456789.eE".IndexOf(text[position]) >= 0) position++;
        return double.Parse(text.Substring(start, position - start), NumberStyles.Float, CultureInfo.InvariantCulture);
    }

    private static void Expect(string text, ref int position, string word)
    {
        if (string.CompareOrdinal(text, position, word, 0, word.Length) != 0) throw Error(text, position, $"expected '{word}'");
        position += word.Length;
    }

    private static char Peek(string text, int position) => position < text.Length ? text[position] : '\0';

    private static void SkipWhitespace(string text, ref int position)
    {
        while (position < text.Length && (text[position] == ' ' || text[position] == '\t' || text[position] == '\n' || text[position] == '\r' || text[position] == '\uFEFF')) position++;
    }

    private static FormatException Error(string text, int position, string message) => new($"Invalid JSON at {position}: {message}.");
}
